package net.zartra.gui;
import org.bukkit.*;import org.bukkit.entity.Player;import org.bukkit.inventory.*;import java.io.*;import java.util.*;
final class MenuManager {private final MenuStorage store;private Map<String,MenuDefinition> menus;MenuManager(MenuStorage s){store=s;menus=s.load();}static boolean validId(String id){return id!=null&&id.matches("[a-z0-9_-]{1,32}");}MenuDefinition get(String id){return id==null?null:menus.get(id.toLowerCase());}Collection<MenuDefinition> all(){return menus.values();}MenuDefinition create(String id){MenuDefinition d=new MenuDefinition(id,id,3);menus.put(id,d);return d;}void save(MenuDefinition d)throws IOException{store.save(d);}void saveAll()throws IOException{for(MenuDefinition d:menus.values())store.save(d);}MenuDefinition duplicate(MenuDefinition s,String id){MenuDefinition d=new MenuDefinition(id,s.title,s.rows);d.openingCommand=s.openingCommand;d.openingPermission=s.openingPermission;d.permissionDenied=s.permissionDenied;d.openingSound=s.openingSound;d.closingSound=s.closingSound;d.refreshInterval=s.refreshInterval;d.closeAfterAction=s.closeAfterAction;for(Map.Entry<Integer,MenuItem> e:s.items.entrySet()){MenuItem o=e.getValue(),n=new MenuItem(o.stack(),null);n.data=o.data;n.cooldown=o.cooldown;n.closeAfterAction=o.closeAfterAction;for(MenuClickType t:MenuClickType.values())for(ActionEntry a:o.actions(t))n.actions(t).add(a.copy());d.items.put(e.getKey(),n);}menus.put(id,d);return d;}boolean delete(String id){menus.remove(id);return store.delete(id);}void reload(){menus=store.load();}void open(Player p,MenuDefinition d){if(d.openingPermission!=null&&!d.openingPermission.isEmpty()&&!p.hasPermission(d.openingPermission)){p.sendMessage(Chat.c(d.permissionDenied));return;}Inventory i=Bukkit.createInventory(new Holder(d.id,false,Screen.NONE),d.rows*9,Chat.c(d.title));for(Map.Entry<Integer,MenuItem> e:d.items.entrySet())i.setItem(e.getKey(),e.getValue().stack());p.openInventory(i);if(d.openingSound!=null&&!d.openingSound.isEmpty())try{p.playSound(p.getLocation(),Sound.valueOf(d.openingSound.toUpperCase()),1F,1F);}catch(Exception ex){}}
 enum Screen{NONE,MAIN,LIST,ACTIONS,ACTION_LIST,ACTION_EDIT,ACTION_DELETE}static final class Holder implements InventoryHolder{final String id;final boolean edit;final Screen screen;final int slot,action;final MenuClickType type;Holder(String id,boolean edit,Screen s){this(id,edit,s,-1,null,-1);}Holder(String id,boolean edit,Screen s,int slot){this(id,edit,s,slot,null,-1);}Holder(String id,boolean edit,Screen s,int slot,MenuClickType type,int action){this.id=id;this.edit=edit;screen=s;this.slot=slot;this.type=type;this.action=action;}public Inventory getInventory(){return null;}}
}